pred_answer:
# Read the input
A = list(map(int, input().split()))

# Check if the list is already sorted
if A == sorted(A):
    print("No")
else:
    # Count the number of inversions (positions where A[i] > A[i+1])
    inversions = 0
    for i in range(4):
        if A[i] > A[i+1]:
            inversions += 1
    # If there are exactly two inversions (which can be fixed by one swap), then print Yes
    if inversions == 2:
        print("Yes")
    else:
        print("No")

